// A UMD wrapper as every minifier emits it: the module body is ONE
// statement, `!function(root, factory){...}(globalRef, factory)`. The `!`
// only forces the function to parse as an expression -- the boolean it
// produces is discarded, and the wrapper returns nothing, so the operand's
// type is `void`, which has no ToBoolean of its own.
!function (n, o) {
    o("undefined" != typeof n ? "global" : "none");
}("undefined" != typeof globalThis ? globalThis : this, function (e) {
    console.log("factory ran:", e);
});
exports.ok = true;
